package com.donotmiss.backend.aiapplication.career;
import com.donotmiss.backend.aiapplication.evidence.CandidateEvidenceSourceType; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="candidate_evidences") public class CandidateEvidenceEntity{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="user_id",nullable=false,length=80,updatable=false) private String userId; @Column(name="profile_snapshot_id",nullable=false,updatable=false) private Long profileSnapshotId; @Column(name="resume_version_id",nullable=false,updatable=false) private Long resumeVersionId;
 @Enumerated(EnumType.STRING) @Column(name="source_type",nullable=false,length=32,updatable=false) private CandidateEvidenceSourceType sourceType; @Column(name="source_id",nullable=false,length=120,updatable=false) private String sourceId; @Column(name="source_reference",nullable=false,length=240,updatable=false) private String sourceReference; @Column(name="skill_code",nullable=false,length=100,updatable=false) private String skillCode; @Column(nullable=false,length=600,updatable=false) private String claim; @Column(name="evidence_text",nullable=false,columnDefinition="text",updatable=false) private String evidenceText; @Column(nullable=false,precision=5,scale=4,updatable=false) private BigDecimal confidence; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt;
 @PrePersist void create(){if(createdAt==null)createdAt=Instant.now();} public Long getId(){return id;} public String getUserId(){return userId;} public void setUserId(String v){userId=v;} public Long getProfileSnapshotId(){return profileSnapshotId;} public void setProfileSnapshotId(Long v){profileSnapshotId=v;} public Long getResumeVersionId(){return resumeVersionId;} public void setResumeVersionId(Long v){resumeVersionId=v;} public CandidateEvidenceSourceType getSourceType(){return sourceType;} public void setSourceType(CandidateEvidenceSourceType v){sourceType=v;} public String getSourceId(){return sourceId;} public void setSourceId(String v){sourceId=v;} public String getSourceReference(){return sourceReference;} public void setSourceReference(String v){sourceReference=v;} public String getSkillCode(){return skillCode;} public void setSkillCode(String v){skillCode=v;} public String getClaim(){return claim;} public void setClaim(String v){claim=v;} public String getEvidenceText(){return evidenceText;} public void setEvidenceText(String v){evidenceText=v;} public BigDecimal getConfidence(){return confidence;} public void setConfidence(BigDecimal v){confidence=v;} public Instant getCreatedAt(){return createdAt;}
}
